import{_ as t,o as s,c as e,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 10 章 写代码：脚本、修改与调试","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 10 章 写代码：脚本、修改与调试.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 10 章 写代码：脚本、修改与调试.md"}'),l={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 10 章 写代码：脚本、修改与调试.md"};function i(o,a,d,r,p,h){return s(),e("div",null,[...a[0]||(a[0]=[n(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 10 章 写代码：脚本、修改与调试（易懂版）](../../easy/第10章 写代码：脚本、修改与调试（易懂版）.md)</p></div><h1 id="第-10-章-写代码-脚本、修改与调试" tabindex="-1">第 10 章 写代码：脚本、修改与调试 <a class="header-anchor" href="#第-10-章-写代码-脚本、修改与调试" aria-label="Permalink to &quot;第 10 章 写代码：脚本、修改与调试&quot;">​</a></h1><blockquote><p>本章目标：掌握代码类任务的三类场景与铁律——写脚本、改代码、调试的方法论，以及代码任务的安全边界。<strong>写代码，AI 赢在速度和广度；验证和放行，永远在你手里。</strong></p></blockquote><h2 id="_10-1-场景-代码是我的核心战场" tabindex="-1">10.1 场景：代码是我的核心战场 <a class="header-anchor" href="#_10-1-场景-代码是我的核心战场" aria-label="Permalink to &quot;10.1 场景：代码是我的核心战场&quot;">​</a></h2><p>代码类任务是我的核心场景之一，包括三类：</p><table tabindex="0"><thead><tr><th>场景</th><th>说明</th><th>典型例子</th></tr></thead><tbody><tr><td><strong>写脚本</strong></td><td>自动化、批处理、数据处理</td><td>批量改名、爬取数据、统计报表</td></tr><tr><td><strong>改代码</strong></td><td>修 bug、加功能、重构</td><td>修报错、加参数、拆分模块</td></tr><tr><td><strong>调试</strong></td><td>定位报错、分析日志、验证修复</td><td>排查 KeyError、分析崩溃日志</td></tr></tbody></table><h2 id="_10-2-写代码的四条铁律" tabindex="-1">10.2 写代码的四条铁律 <a class="header-anchor" href="#_10-2-写代码的四条铁律" aria-label="Permalink to &quot;10.2 写代码的四条铁律&quot;">​</a></h2><h3 id="_10-2-1-铁律一-先读后改" tabindex="-1">10.2.1 铁律一：先读后改 <a class="header-anchor" href="#_10-2-1-铁律一-先读后改" aria-label="Permalink to &quot;10.2.1 铁律一：先读后改&quot;">​</a></h3><p><strong>改任何代码前，先 Read 完整上下文。</strong> 就像医生开药前先看病史：</p><ul><li>不读就改 = 盲人摸象，改坏的概率极高；</li><li>先读上下文 = 理解设计意图，最小改动到位。</li></ul><h3 id="_10-2-2-铁律二-最小改动" tabindex="-1">10.2.2 铁律二：最小改动 <a class="header-anchor" href="#_10-2-2-铁律二-最小改动" aria-label="Permalink to &quot;10.2.2 铁律二：最小改动&quot;">​</a></h3><p><strong>能改一行不重写十行，diff 越小越安全。</strong></p><table tabindex="0"><thead><tr><th>做法</th><th>风险</th></tr></thead><tbody><tr><td>整段重写</td><td>新代码引入新问题，diff 无法 review</td></tr><tr><td>最小修改</td><td>改动一目了然，回退容易，review 快</td></tr></tbody></table><h3 id="_10-2-3-铁律三-验证优先" tabindex="-1">10.2.3 铁律三：验证优先 <a class="header-anchor" href="#_10-2-3-铁律三-验证优先" aria-label="Permalink to &quot;10.2.3 铁律三：验证优先&quot;">​</a></h3><p><strong>写完必须跑，不能&quot;我觉得没问题&quot;。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写代码 → 跑测试/运行验证 → 确认结果 → 才交付</span></span></code></pre></div><p>&quot;我觉得没问题&quot;是 bug 的温床。&quot;测试通过了&quot;才是交付的依据。</p><h3 id="_10-2-4-铁律四-可回退" tabindex="-1">10.2.4 铁律四：可回退 <a class="header-anchor" href="#_10-2-4-铁律四-可回退" aria-label="Permalink to &quot;10.2.4 铁律四：可回退&quot;">​</a></h3><p><strong>让你能看到改动内容，随时可以撤销。</strong></p><ul><li>展示 diff 让你 review；</li><li>保留旧版本（或依赖 git 管理）；</li><li>不擅自覆盖不可逆资源。</li></ul><h2 id="_10-3-案例一-写一个批处理脚本" tabindex="-1">10.3 案例一：写一个批处理脚本 <a class="header-anchor" href="#_10-3-案例一-写一个批处理脚本" aria-label="Permalink to &quot;10.3 案例一：写一个批处理脚本&quot;">​</a></h2><h3 id="_10-3-1-指令" tabindex="-1">10.3.1 指令 <a class="header-anchor" href="#_10-3-1-指令" aria-label="Permalink to &quot;10.3.1 指令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写一个 PowerShell 脚本，把 downloads/ 下所有 .jpg 按拍摄日期</span></span>
<span class="line"><span>重命名（IMG_YYYYMMDD_序号.jpg），并输出处理日志。</span></span>
<span class="line"><span>要求：先试运行（-WhatIf），确认无误再真正执行。</span></span></code></pre></div><h3 id="_10-3-2-我的做法-逐步拆解" tabindex="-1">10.3.2 我的做法（逐步拆解） <a class="header-anchor" href="#_10-3-2-我的做法-逐步拆解" aria-label="Permalink to &quot;10.3.2 我的做法（逐步拆解）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① Glob 查看目录：有多少文件？命名规律？是否有重名风险？</span></span>
<span class="line"><span>② 写脚本，加 -WhatIf 干跑模式</span></span>
<span class="line"><span>③ 先试运行 → 把&quot;将要执行的动作&quot;列成清单给你看</span></span>
<span class="line"><span>④ 你确认无误 → 正式执行 → 输出处理日志（改了几个、失败几个）</span></span>
<span class="line"><span>⑤ 抽查改名结果 → 汇报</span></span></code></pre></div><h3 id="_10-3-3-为什么要-试运行" tabindex="-1">10.3.3 为什么要&quot;试运行&quot; <a class="header-anchor" href="#_10-3-3-为什么要-试运行" aria-label="Permalink to &quot;10.3.3 为什么要&quot;试运行&quot;&quot;">​</a></h3><p><strong>试运行 = 免费的安全网。</strong> 批量操作不可逆，先干跑一遍&quot;将要做什么&quot;，把风险暴露在你确认之前。凡是批量、不可逆的操作，我都坚持&quot;先干跑，后真跑&quot;。</p><h2 id="_10-4-案例二-修一个-bug" tabindex="-1">10.4 案例二：修一个 bug <a class="header-anchor" href="#_10-4-案例二-修一个-bug" aria-label="Permalink to &quot;10.4 案例二：修一个 bug&quot;">​</a></h2><h3 id="_10-4-1-指令" tabindex="-1">10.4.1 指令 <a class="header-anchor" href="#_10-4-1-指令" aria-label="Permalink to &quot;10.4.1 指令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/app.py 运行报 KeyError: &#39;user_id&#39;，帮我定位并修复。</span></span>
<span class="line"><span>报错堆栈：</span></span>
<span class="line"><span>（贴堆栈）</span></span></code></pre></div><h3 id="_10-4-2-我的做法-完整流程" tabindex="-1">10.4.2 我的做法（完整流程） <a class="header-anchor" href="#_10-4-2-我的做法-完整流程" aria-label="Permalink to &quot;10.4.2 我的做法（完整流程）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① Read app.py → 看现场（先读后改）</span></span>
<span class="line"><span>② Grep &#39;user_id&#39; → 查所有相关位置（找全引用）</span></span>
<span class="line"><span>③ 判断根因方向：</span></span>
<span class="line"><span>   - 字段名拼写不一致？</span></span>
<span class="line"><span>   - 数据源缺这个字段？</span></span>
<span class="line"><span>   - 处理顺序问题（先用了后赋值）？</span></span>
<span class="line"><span>④ 读关联文件（数据源/调用方）确认</span></span>
<span class="line"><span>⑤ Edit 最小修复</span></span>
<span class="line"><span>⑥ 跑测试/复现命令 → 验证修复生效</span></span>
<span class="line"><span>⑦ 展示 diff → 你 review</span></span></code></pre></div><h3 id="_10-4-3-调试中的二分定位" tabindex="-1">10.4.3 调试中的二分定位 <a class="header-anchor" href="#_10-4-3-调试中的二分定位" aria-label="Permalink to &quot;10.4.3 调试中的二分定位&quot;">​</a></h3><p><strong>调试不是瞎试，而是二分定位：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>复现 → 缩小范围（注释掉一半代码）→ 定位到函数 → 定位到行</span></span>
<span class="line"><span>→ 确认根因 → 修复 → 验证</span></span></code></pre></div><p>每次二分把问题空间砍一半，通常 4~6 轮就能定位。我可以帮你做大部分定位工作，但<strong>根因判断需要你提供业务背景</strong>——这正是人机协作最有价值的地方。</p><h2 id="_10-5-调试方法论-从现象到根因" tabindex="-1">10.5 调试方法论：从现象到根因 <a class="header-anchor" href="#_10-5-调试方法论-从现象到根因" aria-label="Permalink to &quot;10.5 调试方法论：从现象到根因&quot;">​</a></h2><h3 id="_10-5-1-调试四问" tabindex="-1">10.5.1 调试四问 <a class="header-anchor" href="#_10-5-1-调试四问" aria-label="Permalink to &quot;10.5.1 调试四问&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>目的</th></tr></thead><tbody><tr><td>必然复现还是偶发？</td><td>偶发 → 排查并发/时序/环境</td></tr><tr><td>改动后出现的吗？</td><td>是 → 重点查最近改动</td></tr><tr><td>只影响一条数据？</td><td>是 → 查特定数据特征</td></tr><tr><td>有完整报错堆栈吗？</td><td>有 → 从堆栈最深层开始</td></tr></tbody></table><h3 id="_10-5-2-让我帮你调-bug-时-最好给什么" tabindex="-1">10.5.2 让我帮你调 bug 时，最好给什么 <a class="header-anchor" href="#_10-5-2-让我帮你调-bug-时-最好给什么" aria-label="Permalink to &quot;10.5.2 让我帮你调 bug 时，最好给什么&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 报错信息/堆栈（完整）</span></span>
<span class="line"><span>② 触发步骤（怎么复现）</span></span>
<span class="line"><span>③ 最近改动（改了什么之后开始坏的）</span></span>
<span class="line"><span>④ 预期行为（应该是什么样）</span></span></code></pre></div><p><strong>这四样给齐，我定位 bug 的速度能快一倍。</strong></p><h2 id="_10-6-代码任务的边界与安全" tabindex="-1">10.6 代码任务的边界与安全 <a class="header-anchor" href="#_10-6-代码任务的边界与安全" aria-label="Permalink to &quot;10.6 代码任务的边界与安全&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>我的做法</th></tr></thead><tbody><tr><td>执行有副作用的命令（删除/覆盖/装依赖/推远程）</td><td><strong>先问你</strong></td></tr><tr><td>敏感信息（密钥/密码）</td><td>明确告知：不要写进代码和记忆</td></tr><tr><td>生产环境操作</td><td>先给影响评估，再执行</td></tr></tbody></table><h3 id="_10-6-1-脚本安全三问" tabindex="-1">10.6.1 脚本安全三问 <a class="header-anchor" href="#_10-6-1-脚本安全三问" aria-label="Permalink to &quot;10.6.1 脚本安全三问&quot;">​</a></h3><p>写任何脚本前，先过这三问：</p><ol><li><strong>这个操作可逆吗？</strong>（删除文件 = 不可逆 → 先备份/干跑）</li><li><strong>影响范围多大？</strong>（全目录 = 大 → 先小范围试）</li><li><strong>有失败兜底吗？</strong>（出错了会怎样 → 写日志、留现场）</li></ol><h2 id="_10-7-从脚本到工具-沉淀复用" tabindex="-1">10.7 从脚本到工具：沉淀复用 <a class="header-anchor" href="#_10-7-从脚本到工具-沉淀复用" aria-label="Permalink to &quot;10.7 从脚本到工具：沉淀复用&quot;">​</a></h2><p>写好用的脚本，别让它躺在目录里吃灰：</p><table tabindex="0"><thead><tr><th>沉淀方式</th><th>说明</th></tr></thead><tbody><tr><td>存 scripts/ 目录</td><td>统一管理，加注释和参数说明</td></tr><tr><td>封装为 Skill</td><td>一句话触发，自动执行（见第 17 章）</td></tr><tr><td>记入记忆</td><td>&quot;用户环境是 Windows/PowerShell&quot;</td></tr></tbody></table><p><strong>好脚本 = 参数化 + 有注释 + 有日志 + 有失败处理。</strong></p><h2 id="_10-8-练习" tabindex="-1">10.8 练习 <a class="header-anchor" href="#_10-8-练习" aria-label="Permalink to &quot;10.8 练习&quot;">​</a></h2><ol><li>给我一个真实的批处理需求，要求先试运行再执行；</li><li>给我一个报错信息（含堆栈），让我走一遍&quot;定位 → 修复 → 验证&quot;；</li><li>把常用的调试指令存成记忆或 Skill；</li><li>用 10.6 的脚本安全三问，评估你手头的一个脚本。</li></ol><hr><blockquote><p>小结：写代码，AI 赢在速度和广度；<strong>验证和放行，永远在你手里。</strong> 四铁律（先读后改/最小改动/验证优先/可回退）+ 二分定位 + 安全三问，就是代码协作的全部心法。下一章：文件与目录的整理术。</p></blockquote>`,55)])])}const b=t(l,[["render",i]]);export{u as __pageData,b as default};
